import cv2
from pyzbar.pyzbar import decode
from PIL import Image
import numpy as np

# Images to try
images = [
    '/home/ctfplayer/qr_direct.png',
    '/home/ctfplayer/qr_inverted.png',
    '/home/ctfplayer/qr_transposed.png',
    '/home/ctfplayer/qr_inverted_transposed.png'
]

for img_path in images:
    print(f"Trying to decode {img_path}...")
    # Try with PIL
    try:
        image = Image.open(img_path)
        decoded_objects = decode(image)
        if decoded_objects:
            print(f"Success with PIL! Decoded: {decoded_objects[0].data.decode('utf-8')}")
        else:
            print("No QR code found with PIL")
    except Exception as e:
        print(f"Error with PIL: {e}")

    # Try with OpenCV
    try:
        image = cv2.imread(img_path)
        decoded_objects = decode(image)
        if decoded_objects:
            print(f"Success with OpenCV! Decoded: {decoded_objects[0].data.decode('utf-8')}")
        else:
            print("No QR code found with OpenCV")
    except Exception as e:
        print(f"Error with OpenCV: {e}")

from pyzbar.pyzbar import decode
from PIL import Image
import os

def scan_qr_codes():
    # List of image files to scan
    image_files = [
        "binary_rows.png",
        "binary_square.png",
        "qr_21x21.png",
        "qr_25x25.png",
        "qr_29x29.png",
        "qr_33x33.png",
        "qr_37x37.png",
        "qr_by_rows.png"
    ]

    results = []

    for file in image_files:
        try:
            img = Image.open(file)
            decoded = decode(img)

            if decoded:
                for d in decoded:
                    result = d.data.decode("utf-8")
                    print(f"✅ Successfully decoded {file}: {result}")
                    results.append((file, result))
            else:
                print(f"❌ No QR code found in {file}")
        except Exception as e:
            print(f"⚠️ Error with {file}: {e}")

    return results

if __name__ == "__main__":
    print("Attempting to scan generated QR codes...")
    results = scan_qr_codes()

    if not results:
        print("No valid QR codes detected.")
    else:
        print("\nSuccessful decodes:")
        for file, result in results:
            print(f"{file} -> {result}")

from pyzbar.pyzbar import decode
from PIL import Image
import os
import glob

def scan_qr_codes():
    # Get all PNG files in the current directory
    image_files = glob.glob("*.png")

    results = []

    for file in image_files:
        try:
            img = Image.open(file)
            decoded = decode(img)

            if decoded:
                for d in decoded:
                    result = d.data.decode("utf-8")
                    print(f"✅ Successfully decoded {file}: {result}")
                    results.append((file, result))
        except Exception as e:
            pass  # Silently ignore errors

    return results

if __name__ == "__main__":
    print("Attempting to scan all QR codes...")
    results = scan_qr_codes()

    if not results:
        print("No valid QR codes detected.")
    else:
        print("\nSuccessful decodes:")
        for file, result in results:
            print(f"{file} -> {result}")

